# --- 2장이 만든 API 다섯 ---

POST /api/v1/members     쿼리 2   {"id":1}      id 보내면 500
POST /api/v2/members     쿼리 2   {"id":5}
PUT  /api/v2/members/1   쿼리 3   {"id":1,"name":"..."}
GET  /api/v1/members     쿼리 9   500 Infinite recursion
GET  /api/v2/members     쿼리 1   {"count":3,"data":[...]}

# --- 엔티티가 어떻게 됐나 ---

@Entity
public class Member {
    @Id @GeneratedValue
    private Long id;
    private String name;
    @Embedded
    private Address address;
    @OneToMany(mappedBy = "member")
    private List<Order> orders = new ArrayList<>();
}

#   @NotEmpty 없음
#   @JsonIgnore 없음
#   @JsonProperty 없음

#   1편이 만든 그대로다

# --- 그런데 아직 안 건드린 것 ---

GET /orders

#   Session Metrics { 31 JDBC statements were executed }

#   1편 9.4절의 31 이 그대로다

#   2장은 회원만 다뤘다
#   회원은 연관관계를 안 써서 쉬웠다

# --- 주문을 DTO 로 만들어 보면 (미리) ---

#   List<Order> -> List<SimpleOrderDto>
#     dto.name = order.getMember().getName()   <- 프록시를 깬다
#     dto.address = order.getDelivery().getAddress()

GET /api/v2/simple-orders

#   Hibernate: select ... from orders o1_0
#   Hibernate: select ... from member m1_0 where m1_0.member_id=?
#   Hibernate: select ... from delivery d1_0 where d1_0.delivery_id=?
#   Hibernate: select ... from member m1_0 where m1_0.member_id=?
#   Hibernate: select ... from delivery d1_0 where d1_0.delivery_id=?

#   Session Metrics { 5 JDBC statements were executed }

#   DTO 를 썼는데 쿼리가 5개다

#   2.6절의 회원 목록은 1개였다
#   차이는 연관관계를 쓰느냐다

#   이것이 N+1 이다

# --- 2장이 남긴 것 ---

#   고친 것 10
#   연 것 1 (중복 회원 409)
#   미룬 것 4 (7.3절)

